svg.script:
(() => {
    const root=document.documentElement,chart=document.getElementById('demand-edit-chart');
    let bounds=[6.5,23.5,7.25,9,17.5,19],knobs={"amPeak":1,"pmPeak":0.78,"sharpness":1},held=null;
    const frames=[{"bounds":[6.5,23.5,7.25,9,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[6.5,23.5,7.25,9,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[6.5,23.5,7.25,9,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[6.425925925925926,23.5,7.25,9.074074074074074,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[6.2407407407407405,23.5,7.25,9.25925925925926,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[6,23.5,7.25,9.5,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.7592592592592595,23.5,7.25,9.74074074074074,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.574074074074074,23.5,7.25,9.925925925925926,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.0407407407407407,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.1425925925925926,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.275,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.4074074074074074,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.5092592592592595,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":0.78,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":0.817037037037037,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":0.9096296296296297,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.03,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.1503703703703705,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.242962962962963,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.037037037037037}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.1296296296296295}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.25}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.3703703703703702}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.462962962962963}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.5}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.5}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.5}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.5}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.5}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.5}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.5}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.5}},{"bounds":[5.5,23.5,7.25,10,17.5,19],"knobs":{"amPeak":1.55,"pmPeak":1.28,"sharpness":1.5}},{"bounds":[5.54296875,23.5,7.25,9.95703125,17.5,19],"knobs":{"amPeak":1.5263671875,"pmPeak":1.258515625,"sharpness":1.478515625}},{"bounds":[5.65625,23.5,7.25,9.84375,17.5,19],"knobs":{"amPeak":1.4640625,"pmPeak":1.201875,"sharpness":1.421875}},{"bounds":[5.81640625,23.5,7.25,9.68359375,17.5,19],"knobs":{"amPeak":1.3759765625,"pmPeak":1.121796875,"sharpness":1.341796875}},{"bounds":[6,23.5,7.25,9.5,17.5,19],"knobs":{"amPeak":1.275,"pmPeak":1.03,"sharpness":1.25}},{"bounds":[6.18359375,23.5,7.25,9.31640625,17.5,19],"knobs":{"amPeak":1.1740234375,"pmPeak":0.938203125,"sharpness":1.158203125}},{"bounds":[6.34375,23.5,7.25,9.15625,17.5,19],"knobs":{"amPeak":1.0859375,"pmPeak":0.858125,"sharpness":1.078125}},{"bounds":[6.45703125,23.5,7.25,9.04296875,17.5,19],"knobs":{"amPeak":1.0236328125,"pmPeak":0.801484375,"sharpness":1.021484375}},{"bounds":[6.5,23.5,7.25,9,17.5,19],"knobs":{"amPeak":1,"pmPeak":0.78,"sharpness":1}}],sliders=[{"label":"早高峰量","key":"amPeak","range":{"x":81.70967741935485,"y":535.8253528225806,"w":288.06451612903226,"h":24.516129032258064},"value":{"x":327.1822076612903,"y":509.77696572580646,"w":39.52746975806451,"h":19.919354838709676},"limits":[0,2.5]},{"label":"晚高峰量","key":"pmPeak","range":{"x":382.0322580645161,"y":535.8253528225806,"w":288.06451612903226,"h":24.516129032258064},"value":{"x":637.3926411290322,"y":509.77696572580646,"w":29.639616935483872,"h":19.919354838709676},"limits":[0,2.5]},{"label":"波形陡峭度","key":"sharpness","range":{"x":682.3548387096774,"y":535.8253528225806,"w":288.06451612903226,"h":24.516129032258064},"value":{"x":927.8273689516129,"y":509.77696572580646,"w":39.52746975806451,"h":19.919354838709676},"limits":[0.4,2]}],model={"am":8,"pm":18,"mid":12.5,"sigma":{"am":0.85,"pm":1.05,"midday":2.2},"floor":0.06,"midday":0.18,"factors":{"peak":1,"offpeak":0.6,"late":0.25},"day":1.15,"shoulderOpen":6.5,"shoulderClose":22.5},baseRate=1800;
    const px=hour => 26 + hour / 24 * 416,clock=hour => { const m=Math.round(hour*60); return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0'); },times=b => `Open ${clock(b[0])}–${clock(b[1])} · AM peak ${clock(b[2])}–${clock(b[3])} · PM peak ${clock(b[4])}–${clock(b[5])}`;
    const text=(id,value)=>{const g=document.getElementById(id),t=g.querySelector('text');g.replaceChildren(t);t.setAttribute('opacity','1');t.textContent=value;};
    const stop=()=>{if(root.hasAttribute('data-demand-interactive'))return;
      const f=frames[Math.min(48,Math.round(root.getCurrentTime()%24*2))];bounds=[...f.bounds];knobs={...f.knobs};
      root.querySelectorAll('.demand-motion').forEach(el=>el.remove());root.setAttribute('data-demand-interactive','');};
    const draw=()=>{
      const gauss=(h,mu,sigma)=>Math.exp(-((h-mu)**2)/(2*sigma*sigma));
      const rates=Array.from({length:97},(_,i)=>{const h=(i/4)%24,s=knobs.sharpness;
        const shape=model.floor+knobs.amPeak*gauss(h,model.am,model.sigma.am*s)+knobs.pmPeak*gauss(h,model.pm,model.sigma.pm*s)+model.midday*gauss(h,model.mid,model.sigma.midday*s);
        const factor=h<bounds[0]||h>=bounds[1]?model.factors.late:((h>=bounds[2]&&h<bounds[3])||(h>=bounds[4]&&h<bounds[5]))?model.factors.peak:(h<model.shoulderOpen||h>=model.shoulderClose)?model.factors.late:model.factors.offpeak;return shape*factor*model.day;});
      const top=Math.ceil(Math.max(1,...rates)*10)/10+.1,by=97-83/top;
      document.getElementById('demand-live-line').setAttribute('points',rates.map((r,i)=>px(i/4)+','+(97-r/top*83)).join(' '));
      const base=document.getElementById('demand-baseline');base.setAttribute('y1',by);base.setAttribute('y2',by);
      text('demand-top',Math.round(top*100)+'%');text('demand-count-top',Math.round(top*baseRate).toLocaleString('en-US'));
      document.getElementById('demand-count-base').setAttribute('y',by+3);text('demand-live-times',times(bounds));
      for(const i of [0,2,4]){const r=document.getElementById('demand-band-'+i);r.setAttribute('x',px(bounds[i]));r.setAttribute('width',px(bounds[i+1])-px(bounds[i]));}
      bounds.forEach((v,i)=>{document.getElementById('demand-grip-'+i).setAttribute('transform','translate('+px(v)+',0)');chart.querySelector('[data-boundary="'+i+'"]').setAttribute('aria-valuenow',Math.round(v*60));});
      sliders.forEach((s,i)=>{const r=s.range,l=r.x+6,v=knobs[s.key],p=l+(v-s.limits[0])/(s.limits[1]-s.limits[0])*(r.w-12);
        document.getElementById('demand-slider-thumb-'+i).setAttribute('cx',p);document.getElementById('demand-slider-fill-'+i).setAttribute('width',p-l);
        text('demand-slider-value-'+i,Math.round(v*100)+'%');root.querySelector('[data-knob="'+i+'"]').setAttribute('aria-valuenow',Math.round(v*100));});};
    const set=(hit,clientX,clientY,delta)=>{stop();
      if(hit.hasAttribute('data-boundary')){const i=Number(hit.dataset.boundary),p=new DOMPoint(clientX,clientY).matrixTransform(chart.getScreenCTM().inverse());
        const v=delta===undefined?(p.x-26)/416*24:bounds[i]+delta/60;
        bounds[i]=Math.max(i%2?bounds[i-1]+.25:0,Math.min(i%2?24:bounds[i+1]-.25,Math.round(v*60)/60));
      }else{const s=sliders[Number(hit.dataset.knob)],p=new DOMPoint(clientX,clientY).matrixTransform(root.getScreenCTM().inverse());
        const v=delta===undefined?s.limits[0]+(p.x-s.range.x-6)/(s.range.w-12)*(s.limits[1]-s.limits[0]):knobs[s.key]+delta/100;
        knobs[s.key]=Math.max(s.limits[0],Math.min(s.limits[1],Math.round(v*100)/100));}draw();};
    root.addEventListener('pointerdown',e=>{const hit=e.target.closest('[data-boundary],[data-knob]');if(!hit)return;held={hit,id:e.pointerId};root.setPointerCapture(e.pointerId);set(hit,e.clientX,e.clientY);e.preventDefault();});
    root.addEventListener('pointermove',e=>{if(held&&held.id===e.pointerId)set(held.hit,e.clientX,e.clientY);});
    const end=e=>{if(!held||held.id!==e.pointerId)return;held=null;if(root.hasPointerCapture(e.pointerId))root.releasePointerCapture(e.pointerId);};
    root.addEventListener('pointerup',end);root.addEventListener('pointercancel',end);
    root.addEventListener('keydown',e=>{const hit=e.target.closest('[data-boundary],[data-knob]');if(!hit||!['ArrowLeft','ArrowRight'].includes(e.key))return;
      set(hit,0,0,(e.key==='ArrowRight'?1:-1)*(hit.hasAttribute('data-boundary')?(e.shiftKey?60:15):(e.shiftKey?10:1)));e.preventDefault();});
  })();
